import {DefinitionDangerZone} from '@github-ui/custom-properties-core/components/DefinitionDangerZone'
import {DefinitionReadOnlyOverview} from '@github-ui/custom-properties-core/components/DefinitionReadOnlyOverview'
import {DeleteDefinitionDialog} from '@github-ui/custom-properties-core/components/DeleteDefinitionDialog'
import {PropertiesBreadcrumbsPageHeader} from '@github-ui/custom-properties-core/components/PropertiesBreadcrumbsPageHeader'
import {ServerErrorFormBanner} from '@github-ui/custom-properties-core/components/ServerErrorFormBanner'
import {useBannerContext} from '@github-ui/custom-properties-core/context/BannerContext'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useQueryClient} from '@github-ui/react-query'
import type {SafeHTMLString} from '@github-ui/safe-html'
import {VerifiedHTMLText} from '@github-ui/safe-html/VerifiedHTML'
import {useNavigate} from '@github-ui/use-navigate'
import {PencilIcon} from '@primer/octicons-react'
import {Button} from '@primer/react'
import {useEffect, useRef, useState} from 'react'
import {DefinitionForm} from '../components/DefinitionForm'
import {useBusinessSlug} from '../hooks/use-business-slug'
import {getPropertiesListPath, getPropertiesUsagePath, getPropertyDetailsPath} from '../paths'
import {businessPropertyDefinitionRoute} from './business-property-definition-route'

export function BusinessPropertyDefinitionRoute() {
  const business = useBusinessSlug()
  const queryClient = useQueryClient()
  const navigate = useNavigate()
  const routeQuery = useRouteQuery(businessPropertyDefinitionRoute, 'mainQuery')
  const {definition, propertyNames} = routeQuery.data
  const [isEditing, setIsEditing] = useState(!definition)
  const [showDeleteDialog, setShowDeleteDialog] = useState(false)
  const {setBanner} = useBannerContext()

  /* eslint-disable-next-line @github-ui/github-monorepo/no-cast-as-safe-html-string -- Safe empty string initialization. SECURITY XSS risk: Do not modify with user input. Verified: only replaced with server-sanitized HTML. */
  const [formError, setFormError] = useState<SafeHTMLString>('' as SafeHTMLString)

  const propertyListPath = getPropertiesListPath({business})

  const navigateToList = () => {
    navigate(propertyListPath)
  }

  const onEditSuccess = (propertyName: string) => {
    setIsEditing(false)
    if (definition) {
      setBanner('definition.updated.success')
      queryClient.invalidateQueries({queryKey: routeQuery.queryKey})
    } else {
      setBanner('definition.created.success')
      navigate(businessPropertyDefinitionRoute.generatePath({business, property_name: propertyName}))
    }
  }

  const onEditCancel = () => {
    setIsEditing(false)
    if (!definition) {
      navigateToList()
    }
  }

  const serverErrorBannerRef = useRef<HTMLDivElement>(null)
  const deleteButtonRef = useRef<HTMLButtonElement>(null)

  useEffect(() => {
    serverErrorBannerRef.current?.focus()
  }, [formError, serverErrorBannerRef])

  return (
    <>
      {formError && (
        <div className="tmp-mb-3">
          <ServerErrorFormBanner ref={serverErrorBannerRef}>
            <VerifiedHTMLText html={formError} />
          </ServerErrorFormBanner>
        </div>
      )}
      <PropertiesBreadcrumbsPageHeader
        className="tmp-mb-3"
        pageTitle={definition?.propertyName || 'New property'}
        breadcrumbLinkProps={{to: propertyListPath}}
        actions={
          !isEditing && (
            <Button className="tmp-ml-3 f5 text-semibold" onClick={() => setIsEditing(true)} leadingVisual={PencilIcon}>
              Edit
            </Button>
          )
        }
      />
      {definition && !isEditing ? (
        <>
          <DefinitionReadOnlyOverview>
            <DefinitionReadOnlyOverview.CommonAttributes definition={definition} />
            <DefinitionReadOnlyOverview.DataRow label="Allow organization actors to set this property">
              {definition.valuesEditableBy === 'enterprise_and_org_actors' ? 'Enabled' : 'Disabled'}
            </DefinitionReadOnlyOverview.DataRow>
          </DefinitionReadOnlyOverview>
          <div className="tmp-mt-4">
            <DefinitionDangerZone>
              <DefinitionDangerZone.ActionItem
                title="Delete property"
                subtitle="Permanently delete this property and its values from all organizations."
                onClick={() => setShowDeleteDialog(true)}
                variant="danger"
                ref={deleteButtonRef}
              />
            </DefinitionDangerZone>
          </div>
        </>
      ) : (
        <DefinitionForm
          definition={definition}
          existingPropertyNames={propertyNames}
          onCancel={onEditCancel}
          setFormError={setFormError}
          onSuccess={onEditSuccess}
        />
      )}
      {showDeleteDialog && definition && (
        <DeleteDefinitionDialog
          definition={definition}
          usagePath={getPropertiesUsagePath({business, propertyName: definition.propertyName})}
          deletePath={getPropertyDetailsPath({business, propertyName: definition.propertyName})}
          targetLiterals={{single: 'organization', multiple: 'organizations'}}
          returnFocusRef={deleteButtonRef}
          onCancel={() => setShowDeleteDialog(false)}
          onSuccess={() => {
            setBanner('definition.deleted.success')
            queryClient.invalidateQueries({
              queryKey: ['custom-properties-for-orgs', 'businessCustomPropertiesSettingsRoute'],
            })
            navigateToList()
          }}
        />
      )}
    </>
  )
}
