import type {OrganizationTarget, PropertyDefinition} from '@github-ui/custom-properties-types/org-properties'
import {mainQuery} from '@github-ui/react-core/future/main-query'
import {organizationCustomPropertiesAppBuilder} from '../config/app-builder'

export interface OrganizationPropertiesSettingsRouteResponse {
  definitions: PropertyDefinition[]
  editableProperties: string[]
  currentTarget: OrganizationTarget
}

export const organizationCustomPropertiesSettingsRoute = organizationCustomPropertiesAppBuilder.createQueryRouteConfig(
  'organizationCustomPropertiesSettingsRoute',
  {
    path: '/organizations/:org/settings/org-custom-properties',
    queries: [mainQuery<OrganizationPropertiesSettingsRouteResponse>()],
  },
)
